update user_sessions
set revoked_at     = #{revokedAt},
    revoked_reason = #{reason}
where user_id = #{userId}
  and device_id = #{deviceId}
  and revoked_at is null
  and expires_at > #{revokedAt}

update user_sessions
set revoked_at     = #{revokedAt},
    revoked_reason = #{reason}
where id = #{userSessionId}
  and user_id = #{userId}
  and revoked_at is null
  and expires_at > #{revokedAt}
